<?php
/** Orchard Ledger transport workflow endpoint: only the assigned provider can advance a request through recorded trip milestones. */
declare(strict_types=1);
require_once __DIR__ . '/../../includes/bootstrap.php';
require_method('POST');verify_csrf();$providerUser=require_role(['transport_provider']);$requestId=filter_input(INPUT_POST,'request_id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$next=normalize_text($_POST['status']??'',30);$transitions=['requested'=>['accepted','cancelled'],'accepted'=>['driver_assigned','cancelled'],'driver_assigned'=>['pickup_scheduled','cancelled'],'pickup_scheduled'=>['picked_up','cancelled'],'picked_up'=>['in_transit','cancelled'],'in_transit'=>['delivered','cancelled']];
if(!$requestId)json_response(false,'A valid transport request is required.',[],422);$pdo=db();$pdo->beginTransaction();
try{$request=fetch_one('SELECT tr.*,tp.user_id AS provider_user_id FROM transport_requests tr JOIN transport_providers tp ON tp.id=tr.provider_id WHERE tr.id=:id AND tp.user_id=:user FOR UPDATE',['id'=>$requestId,'user'=>$providerUser['id']]);if($request===null)throw new RuntimeException('This transport request is not assigned to your operation.');if(!in_array($next,$transitions[$request['status']]??[],true))throw new RuntimeException('This transport request cannot move to that status.');$pdo->prepare('UPDATE transport_requests SET status=:status WHERE id=:id')->execute(['status'=>$next,'id'=>$requestId]);$pdo->prepare('INSERT INTO transport_status_history (transport_request_id,status,changed_by_user_id,note) VALUES (:request,:status,:actor,:note)')->execute(['request'=>$requestId,'status'=>$next,'actor'=>$providerUser['id'],'note'=>'Transport provider updated request status.']);create_notification((int)$request['farmer_id'],'transport_'.$next,'Transport request '.ucwords(str_replace('_',' ',$next)),'Your transport request '.$request['reference_code'].' is now '.str_replace('_',' ',$next),'farmer/dashboard.php','transport_request',$requestId);$pdo->commit();audit_log((int)$providerUser['id'],'transport_'.$next,'transport_requests',$requestId);json_response(true,'Transport request status updated to '.ucwords(str_replace('_',' ',$next)).'.',['request_id'=>$requestId,'status'=>$next]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();json_response(false,$e instanceof RuntimeException?$e->getMessage():'The transport status could not be updated.',[],422);}
